package com.mewcode.memory;
import com.mewcode.tool.Tool;import com.mewcode.tool.ToolCategory;import com.mewcode.tool.ToolResult;import java.nio.file.Path;import java.util.ArrayList;import java.util.List;import java.util.Map;
public final class MemorySearchTool implements Tool {private final SqliteMemoryStore user;private final SqliteMemoryStore project;public MemorySearchTool(Path workspace){user=new SqliteMemoryStore(Path.of(System.getProperty("user.home"),".mewcode","memory.db"));project=new SqliteMemoryStore(workspace.resolve(".mewcode/memory.db"));}public String name(){return "MemorySearch";}public String description(){return "Search durable user and project memories using SQLite FTS5.";}public ToolCategory category(){return ToolCategory.READ;}public boolean shouldDefer(){return true;}public Map<String,Object> schema(){return Map.of("name",name(),"description",description(),"input_schema",Map.of("type","object","properties",Map.of("query",Map.of("type","string")),"required",List.of("query")));}public ToolResult execute(Map<String,Object>a){String q=String.valueOf(a.getOrDefault("query","")).trim();if(q.isEmpty())return ToolResult.error("query is required");var all=new ArrayList<SqliteMemoryStore.Entry>();all.addAll(user.search(q,5));all.addAll(project.search(q,5));if(all.isEmpty())return ToolResult.success("No matching memories");StringBuilder b=new StringBuilder();all.stream().distinct().limit(8).forEach(e->b.append('[').append(e.type()).append("] ").append(e.name()).append(": ").append(e.content()).append('\n'));return ToolResult.success(b.toString().strip());}}
